// 由 scripts/gen-css.mjs 生成（`pnpm run gen:css`）：改样式请改那个 .css 文件后重新生成。
export const EXPLORER_CSS = "/* 工作区文件浏览器（dshpc-fb-*）。类名与 FileBrowser / preview 组件硬编码逐字一致。 */\n.dshpc-fb{display:flex;flex-direction:column;height:100%;min-height:0;color:var(--dshpc-fg);font-size:13px}\n.dshpc-fb--dock{height:100%;border-left:1px solid var(--dshpc-border-faint)}\n.dshpc-fb--resizing{contain:layout paint}\n.dshpc-fb--resizing .dshpc-fb__frame{pointer-events:none}\n.dshpc-fb__resizer{position:absolute;top:0;bottom:0;left:0;width:4px;cursor:col-resize;z-index:2}\n.dshpc-fb__resizer:hover{background:var(--dshpc-open-bg)}\n\n/* 第一排：▾ 选层 + 面包屑 + 动作 */\n.dshpc-fb__bar{display:flex;align-items:center;gap:2px;padding:6px 8px;border-bottom:1px solid var(--dshpc-border-faint);min-width:0}\n.dshpc-fb__menu-wrap{flex:none;display:flex}\n.dshpc-fb__crumbs{flex:1 1 auto;display:flex;align-items:center;gap:2px;min-width:0;overflow:hidden}\n.dshpc-fb__crumbs-measure{position:absolute;visibility:hidden;pointer-events:none;display:flex;align-items:center;gap:2px;white-space:nowrap}\n.dshpc-fb__crumb{\n  background:none;border:none;padding:2px 4px;border-radius:4px;cursor:pointer;\n  color:var(--dshpc-link);font:inherit;max-width:180px;flex:none;\n}\n.dshpc-fb__crumb:disabled{color:var(--dshpc-fg-4);cursor:default}\n.dshpc-fb__crumb--current{color:var(--dshpc-fg);font-weight:600;cursor:default;min-width:0;max-width:100%}\n.dshpc-fb__crumb-mq{display:inline-block;max-width:160px;vertical-align:bottom}\n.dshpc-fb__crumb-sep{color:var(--dshpc-fg-4);flex:none}\n.dshpc-fb__actions{display:flex;gap:2px;margin-left:auto;flex:none;align-items:center}\n.dshpc-fb__bar-plain{color:var(--dshpc-fg-3);font-size:12px}\n\n/* 第二排（仅预览态）：文件名 + 工具 */\n.dshpc-fb__title{display:flex;align-items:center;gap:8px;padding:6px 8px;border-bottom:1px solid var(--dshpc-border-faint);min-width:0}\n.dshpc-fb__title-inner{font-size:13px;font-weight:600}\n\n/* 主体 */\n.dshpc-fb__body{flex:1;min-height:0;display:flex;align-items:center;justify-content:center;padding:12px}\n.dshpc-fb__tree{flex:1;min-height:0;overflow:auto;padding:4px 0}\n.dshpc-fb__note{padding:6px 10px;color:var(--dshpc-fg-3);font-size:11px}\n.dshpc-fb__err{padding:6px 10px;color:var(--dshpc-fg-3);font-size:12px;text-align:center}\n\n/* 树行 */\n.dshpc-fb__row{display:flex;align-items:center;gap:6px;padding:3px 10px;cursor:pointer;white-space:nowrap}\n.dshpc-fb__row:hover{background:var(--dshpc-surface-sunken)}\n.dshpc-fb__row:focus-visible{outline:2px solid var(--dshpc-link);outline-offset:-2px}\n.dshpc-fb__row-icon{width:18px;flex:none;display:inline-flex;color:var(--dshpc-fg-3)}\n.dshpc-fb__row-name{overflow:hidden;text-overflow:ellipsis;min-width:0}\n.dshpc-fb__row-toggle{\n  flex:none;display:inline-flex;align-items:center;justify-content:center;\n  width:18px;height:18px;padding:0;border:none;border-radius:4px;background:none;\n  color:var(--dshpc-fg-3);cursor:pointer;transition:transform .12s ease;\n}\n.dshpc-fb__row-toggle:hover{background:var(--dshpc-surface-sunken);color:var(--dshpc-fg)}\n.dshpc-fb__row-toggle--open{transform:rotate(90deg)}\n.dshpc-fb__row-act{\n  margin-left:auto;flex:none;border:1px solid var(--dshpc-border);border-radius:4px;\n  background:var(--dshpc-surface-1);color:var(--dshpc-fg-2);font:inherit;font-size:11px;\n  padding:1px 8px;cursor:pointer;\n}\n.dshpc-fb__row-act:hover{color:var(--dshpc-fg);border-color:var(--dshpc-border-strong)}\n.dshpc-fb__row-children{padding-left:14px}\n.dshpc-fb__row-note{padding:4px 10px;color:var(--dshpc-fg-4);font-size:11px}\n.dshpc-fb__row-err{padding:4px 10px;color:var(--dshpc-fg-3);font-size:11px}\n\n/* ▾ 选层菜单条目（官方 Menu portal 内） */\n.dshpc-fb__menu-item{display:flex;align-items:center;gap:6px;padding-left:8px}\n.dshpc-fb__menu-icon{display:inline-flex;align-items:center;flex:none}\n.dshpc-fb__menu-chev-slot{display:inline-block;width:11px;flex:none}\n.dshpc-fb__menu-chev{display:inline-flex;align-items:center;flex:none;color:var(--dshpc-fg-4)}\n\n/* 预览体 */\n.dshpc-fb__text{flex:1;min-height:0;overflow:auto;width:100%}\n.dshpc-fb__banner{padding:6px 10px;background:var(--dshpc-open-bg-soft);color:var(--dshpc-fg-2);font-size:11px}\n.dshpc-fb__more{display:flex;justify-content:center;padding:10px}\n.dshpc-fb__image{max-width:100%;border-radius:6px;border:1px solid var(--dshpc-border-faint)}\n.dshpc-fb__frame{flex:1;width:100%;height:100%;border:none;background:var(--dshpc-surface-1)}\n"
